/* SYCO — self-extracting server bundle.
 * Deploy: put this file + package.json in a repo, host runs "npm install && npm start".
 * It recreates the project files on disk, then boots the real server. */
'use strict';
const fs = require('fs'), path = require('path');
const FILES = {"server/index.js":"","server/sim.js":"","shared/shared.js":"","public/index.html":"","public/manifest.webmanifest":"","public/icon.svg":"","public/sw.js":"","public/js/sprites.js":"","public/js/audio.js":"","public/js/net.js":"","public/js/game.js":"","public/js/ui.js":""};
for (const [p, b64] of Object.entries(FILES)) {
  fs.mkdirSync(path.dirname(p), { recursive: true });
  fs.writeFileSync(p, Buffer.from(b64, 'base64'));
}
require(path.resolve('./server/index.js'));
